function curry2(fn) {
  return (a) => (b) => fn(a, b);
}
function compose(...fns) {
  return (x) => fns.reduceRight((acc, fn) => fn(acc), x);
}

const applyTax = curry2((rate, amount) => amount * (1 + rate));
const roundToInt = (x) => Math.round(x);

const applyTaxAndRound = compose(roundToInt, applyTax(0.05));

console.log(applyTaxAndRound(100));

